('53fc51fb-c75d-3340-8bce-96ee814baa71', '093b6ac2-422a-3afa-bd56-c4cfc8add616', 'bb9c6574-a9bf-3e13-8673-96dfe11c6d48', 1, '봉투', '도윤은 봉투를 뜯었다. 안에는 지도 한 장과, 도윤의 이름이 적힌 쪽지가 있었다.', '2026-11-01T00:00:00Z', true, '94eff38f-6a72-35d3-889d-5ade135f1a94')
